    bag_examples_v2_toast: "🎁 Nous exemples a la teva bossa: idees de regal, una llista per a l'hotel i una per al vol ✨",
    faq_a_bag_examples_list: "Una bossa nova porta exemples que pots canviar o esborrar com qualsevol altra cosa: Casa (compra, receptes, àpats de la setmana), Família (petits moments, una llista per a la festa d'aniversari, activitats i classes), Idees (idees per al cap de setmana, idees de regal segons la proximitat amb la persona i què fer amb els diners estalviats) i Viatges (llocs on vols anar, equipatge per al viatge, equipatge per a l'hotel i una llista per al vol a l'estranger). Una bossa que ja existia rep una sola vegada els més nous, a les seves pròpies butxaques.",
    faq_q_bag_examples_list: "Quins exemples hi ha a La meva bossa?",
    faq_a_nm_me1_guide: "Me – el teu personatge a New Me, en la seva primera forma (Me1). La primera vegada, just després d'unir-t'hi, s'obre un portal de llum amb espurnes tot al voltant i Me en surt volant, explica en uns quants tocs què t'espera i després es queda al costat de cada pregunta: mentre es trien els àpats, escriu amb tu al seu llibre, i un toc al seu consell en mostra un altre. Al final, Me ho celebra amb tu i et porta a fer un tomb curt – i quan el tomb s'acaba, encara té un petit moment més amb tu. Si surts a mitges –de les preguntes o del tomb–, la propera vegada Me s'alegra de veure't i et pregunta si vols continuar des del mateix punt. «Omet», a dalt, salta l'obertura.",
