    nm_m1_tip_ai: "Un menjar que no és a la llista? Més endavant, a «Canvia», el pots escriure amb les teves paraules – i l'IA el calcularà. I ara, triem tu i jo què menjar cada dia – i és clar que sempre es pot canviar ✨",
