    room_genie_again_no: "Ara no",
    room_genie_again_no_msg: "Doncs és hora d’assolir els objectius que ja t’has marcat. Quan arribis al següent – allà t’hi esperarà alguna cosa ✨",
    room_genie_again_q: "Una altra vegada per aquí? ✨ T’agradaria canviar alguna cosa més de la teva vida?",
    room_genie_again_yes: "Sí",
    room_genie_bye: "Fins aviat",
    room_genie_rest: "L’esperit del bosc ara descansa – torna demà ✨",
    faq_a_shop_holidays: "A la Llista de Compres, toca el regal: apareixen per ordre les festes del teu país (el de Configuració), amb les dates, que es calculen soles cada any. Toca una festa per veure una llista ja feta del que se sol comprar per a aquell dia; tot està seleccionat (tret del que ja és a la teva llista), desmarca el que no necessitis i toca «Afegeix a la llista». Dues setmanes abans d'una festa apareix una petita targeta a dalt de la llista; ✕ l'amaga fins a la festa següent.",
    faq_q_shop_holidays: "Com funciona «Què comprar per a la festa»?",
    shop_hol_add: "Afegeix a la llista ({n})",
    shop_hol_added: "Afegits a la llista: {n}",
    shop_hol_btn: "Què comprar per a la festa",
    shop_hol_items_title: "{holiday} – què comprar?",
    shop_hol_not_now: "Ara no",
    faq_a_shop_delivery: "A la Llista de Compres, toca el camió: tria què porta la comanda (tot està seleccionat), quan arriba (avui, demà o un altre dia) i a quina hora (matí, migdia, tarda o «Altres…» per a un horari teu). Aquests productes passen a una targeta «De camí» a dalt de la llista, amb el dia i l'horari. Quan arriba el dia, apareix «Ha arribat la comanda?» a El Meu Dia (i la targeta mostra «Ha arribat?»). Si ha arribat tot, passen a «Tornar a comprar». Si falta alguna cosa, toca el que no ha arribat i torna directament a la llista.",
    faq_a_shop_departments: "La llista s'ordena sola per les seccions del supermercat – fruita i verdura, pa, làctics i ous, carn i peix, rebost, congelats, begudes, snacks, neteja, higiene, nadons i mascotes –, així recorres els passadissos en ordre. La secció es reconeix pel nom del producte. Si un producte ha anat a parar al lloc equivocat, toca'l i tria'n la secció, o «Una altra…» per escriure la teva.",
    faq_a_shop_share_qty: "Sí. Al costat de cada producte, + n'afegeix un més (×2, ×3…) i − en treu un. El botó de compartir a dalt de la Llista de Compres envia tota la llista, ben ordenada per seccions, per WhatsApp, per correu electrònic o com a còpia.",
    faq_a_shop_two_buttons: "Tots dos volen dir «comprat». ✕ és per a una cosa que compres una sola vegada: surt de la llista (i espera a l'arxiu 🗑️ per si ha estat un error). ↺ és per a allò que compres una vegada i una altra: surt de la llista i espera a «Tornar a comprar»; l'obre el petit botó ↺ al costat de la paperera, a la part de baix de la llista, i un toc allà torna un producte a la llista. A «Editar», a dins, pots treure'n un producte. Quan afegeixes un producte, el que ja havies comprat abans apareix com a suggeriment, i si ja és a la llista, simplement passa a ×2 en lloc d'ocupar una segona línia.",
    faq_q_shop_delivery: "Com funciona «He fet una comanda a domicili»?",
    faq_q_shop_departments: "Per què la meva llista de compres està dividida en seccions?",
