    nm_demo_title: "Així funciona un canvi",
    faq_a_new_me_challenge_journal: "Quan s'acaba un repte – gran, mini o el repte de la setmana –, a la celebració hi ha un botó 📝 Com ha anat? que obre una pàgina al diari de reptes: com ha estat (cinc cares), què ha ajudat, què ha costat i què me n'emporto – res no és obligatori, i també es pot fer més tard. El diari és un diamant a la motxilla màgica: cada repte acabat amb la data i el que s'hi ha escrit, el més recent primer – toca'n un per llegir-lo, editar-lo o compartir-lo (només es comparteix el que hi ha a la pàgina). Un repte acabat també rep una medalla als assoliments, a «Reptes que he acabat». El diari de reptes és independent del diari habitual.",
    faq_q_new_me_challenge_journal: "Què és el diari de reptes?",
    nm_badges_challenges: "Reptes que he acabat",
