    nm_chj_take: "Què me n'emporto?",
    nm_chj_title: "Diari de reptes",
    nm_chj_write: "Escriu com ha anat",
    nm_swap_time: "Hora",
    faq_a_ai_reminder_in_text: "Sí: escriu-lo juntament amb la tasca, per exemple «demà a les 17:00 recollir el paquet, amb un recordatori una hora abans». El recordatori es desa a la mateixa tasca: una hora abans, mitja hora, el dia abans, etc., i «recorda-m'ho» sense hora vol dir 10 minuts abans. Un recordatori escrit al text té prioritat sobre el camp de recordatori de la mateixa finestra.",
    faq_q_ai_reminder_in_text: "Puc demanar un recordatori a l'assistent d'IA en la mateixa petició?",
    myday_meals_all_done: "Tots els àpats d'avui estan marcats 🍽️",
    nm_tour_week_text: "Un petit repte per a la setmana. ✓ cada dia – i al final, una clau.",
    books_home_chip: "{title} · pàg. {page}",
    books_home_of: "de {total}",
    books_home_off_toast: "El llibre ha sortit de la pantalla d’inici",
    books_home_on_toast: "El llibre és a la pantalla d’inici 📖",
    books_home_pin: "A la pantalla d’inici",
    books_home_q: "A quina pàgina sóc?",
    books_home_save: "Desar",
    faq_a_books_home_chip: "Sí. Al Racó de lectura, a la targeta d’un llibre que estàs llegint, toca 📌 A la pantalla d’inici. Sota la salutació de la pantalla d’inici apareix un petit botó amb el llibre i la pàgina – toca’l, escriu el número de pàgina nou i desa, i el progrés queda registrat (també al Racó de lectura). Tornar a tocar 📌 el treu. Hi pot haver diversos llibres alhora – un botó per a cadascun – i és igual a tots els dispositius.",
    faq_a_new_me_week_challenge: "Un petit repte d’una setmana, que tries tu. Al passadís hi ha una targeta gran: «En què vols treballar aquesta setmana?» – toca-la, tria un àmbit (amb mi, amb els altres, aprendre i créixer, calma, petits passos valents, casa i rutina) i un repte, i tria quan comença. Els mateixos reptes també són a la pantalla de reptes, sota 🌱 Creixement personal. Cada dia marca un ✓ a la targeta (un dia lliure per setmana), i cada setmana que acaba porta una clau nova per al món secret. «Llegir 2 pàgines al dia» es marca sol amb les pàgines registrades al Racó de lectura. Quan la setmana acaba, 📌 Mantenir-lo com a tasca diària l’afegeix a La Meva Rutina a l’hora que triïs, amb un ✓ cada dia. Només hi ha un repte de la setmana alhora; els reptes grans i mini continuen al seu costat.",
    faq_a_room_genie: "Al porxo davant del mar, un toc a la llàntia d’Aladí fa sortir l’esperit del bosc – i comença una conversa: quin és el teu desig (què t’agradaria canviar a la vida), com es viurà quan es compleixi, què és difícil pel camí i com es pot convertir la situació d’ara en alguna cosa bona. Després, quant de temps portarà aproximadament, un primer petit pas i dos més, i un «si… llavors…» per quan es faci difícil. Al final apareix tot el desig pas a pas, i pot convertir-se en un objectiu a Els Meus Objectius (els passos esdevenen fites del camí, amb data segons el temps triat; allà es pot canviar tot) o desar-se al diari – i aleshores l’esperit s’acomiada. No es desa res si no es tria una de les dues opcions. A partir de la segona visita, l’esperit pregunta primer si t’agradaria canviar alguna cosa més de la teva vida: sí – la mateixa conversa; ara no – un recordatori per assolir els objectius ja marcats. L’esperit surt un cop al dia: després de desar un desig (o després d’«Ara no»), descansa fins a l’endemà. Les preguntes segueixen una manera coneguda de convertir un desig en un pla: desig, resultat, obstacle i pla.",
    faq_q_books_home_chip: "Puc veure el meu llibre i la pàgina a la pantalla d’inici?",
    faq_q_new_me_week_challenge: "Què és el repte de la setmana?",
    faq_q_room_genie: "Què fa el geni de la llàntia?",
