    nm_me_on_screen: "A la pantalla",
    faq_a_new_me_game: "A New Me els botons del joc sempre es queden al mateix lloc – al passadís, a l'habitació secreta i a tot arreu del bosc; només canvia la pintura del mig. A dalt: el dia del camí, les claus, la ratxa i l'energia d'avui (quant s'ha menjat del pla), i a sota la propera missió – el següent àpat a la seva hora (un toc l'obre, amb ✓ L'he menjat). Al costat: tot el dia, reptes i el meu camí, i al costat d'aquests, el repte de la setmana – els seus 7 dies i un ✓ per a avui. A baix: la motxilla màgica (tot New Me – el mapa del món, el meu camí, compres, assoliments, diari de reptes, mesures, fotos, el calendari mensual, la taula diària, recordatoris, el menú en PDF i configuració; s'obre com a pantalla pròpia). El mapa del món, la primera cosa de la motxilla, mostra tots els llocs del bosc – toca un lloc per anar-hi; un lloc tancat mostra quantes claus necessita. Me és el teu personatge al camí del bosc: comença com a Me1, després d'uns quants reptes (4 claus) creix fins a Me2 i cap al final (9 claus) fins a Me3 – amb una transformació que es veu en directe. Toca Me per veure totes les etapes – qualsevol personatge ja assolit es pot triar de nou, de manera que un d'anterior pot tornar. Me flota: s'arrossega amb el dit o amb el ratolí, i l'entrada que toca s'obre (en una de bloquejada es veu quantes claus falten). Me també t'acompanya a cada habitació i lloc, i flota allà on el deixes: arrossega'l a qualsevol lloc, i arrossega l'anell brillant que té a sota per fer-lo girar del tot sobre si mateix; mira cap on es mou (a l'ordinador: les fletxes el mouen, Q i E el giren). Al passadís, la petita 🏠 sota la barra superior torna a la pantalla d'inici; a cada habitació i lloc, el botó de la mateixa cantonada torna al passadís.",
    faq_q_new_me_game: "Com funcionen els botons del joc, el mapa del món i Me?",
