    faq_a_new_me_menu_build: "Primer el qüestionari pregunta quins àpats fas i quan (2 àpats + un berenar, 2 àpats + un sopar lleuger, o tots dos), i si hi ha alguna cosa al vespre – per menjar o per beure, què i a quina hora. Amb «2 àpats + un berenar», els àpats són el dinar (11:30) i el sopar (19:00), i el berenar a les 16:00. Després apareixen totes les opcions d'aquests àpats. Tria fins a 2 preferides per a cada àpat – el menú mostra «això o allò». En algunes opcions (pita i crema, flocs de blat de moro amb llet, alguna cosa lleugera) tries fins a 3 coses que t'agradin, cadascuna amb la seva ració, i el menú mostra «això o allò o allò»; les calories segueixen el que has triat. El cafè i les begudes funcionen igual. Cada tria està equilibrada, així que el dia suma exactament 1.300 o 1.500. Per canviar-ho quan vulguis: ⚙️ Configuració → 🍽️ Crea el teu menú, o «Tria'n fins a 3 que t'agradin» a la targeta de l'àpat.",
    faq_q_new_me_menu_build: "Com es crea el menú de New Me?",
