    faq_a_myday_water_toggle: "Sí. El got d'aigua a El Meu Dia (amb + per a un got més) es mostra per defecte. Per amagar-lo, desactiva «Mostra l'aigua a El Meu Dia» a Configuració > Personalització i calendari. No s'esborra res: el Seguiment d'Aigua continua funcionant, i en tornar a activar l'interruptor el got torna.",
    faq_q_myday_water_toggle: "Puc amagar l'aigua a El Meu Dia?",
    myday_water_toggle_label: "Mostra l'aigua a El Meu Dia",
    faq_a_routine_newme_sync: "Amb New Me, el ⚙️ de La Meva Rutina té un interruptor «Sincronitzar amb New Me». Activat (per defecte), els àpats d'avui de New Me apareixen a El Meu Dia i a La Meva Rutina – al lloc dels àpats de la rutina que s'han amagat. Desactivat, els àpats de New Me surten de tots dos llocs i la rutina torna a ser exactament com era. No s'esborra res: tornar-lo a activar ho recupera tot i pregunta quins àpats de la rutina amagar.",
    faq_q_routine_newme_sync: "Com activo o desactivo la sincronització de New Me amb La Meva Rutina i El Meu Dia?",
