    theme_name_watercolor_wash: "Aquarel·la",
    faq_a_food_list_languages: "La llista d'aliments integrada va començar amb plats israelians i els seus noms en hebreu. En tots els altres idiomes cada aliment apareix amb el seu nom en anglès, i la cerca troba qualsevol nom en anglès que conegui (per exemple, 'broth' troba Clear soup); els aliments que només tenen nom en hebreu no hi surten. El que no sigui a la llista es pot escriure simplement amb les teves paraules: l'estimació amb IA funciona en tots els idiomes.",
    faq_q_food_list_languages: "Per què la llista d'aliments mostra noms en anglès, i menys aliments, en el meu idioma?",
    settings_copyright_line: "© 2026 tots els drets reservats. app desenvolupada per eden zabari.",
    workout_ready_replace_btn: "Substitueix",
    faq_a_sport_workout_ai: "A Els meus entrenaments → ⋯ → Pla amb IA (i, amb la taula buida, també al mosaic al costat dels plans fets). Respon amb uns quants tocs – quantes vegades per setmana, quan, lloc, nivell i objectiu, gairebé tots també amb \"Altres\" – i, si vols, afegeix una línia lliure, com un genoll sensible o córrer 5 km abans de l'estiu. La IA crea una setmana sencera: tipus d'entrenament, dies, hores, durada, intensitat, exercicis i dies de descans. Abans de desar res hi ha una vista prèvia: \"Posar-lo a la meva taula\" (en lloc de la taula o a més d'ella), \"Una altra proposta\" (fins a 3 vegades) o \"Canviar respostes\". El pla és moderat a propòsit, i si esmentes dolor o una lesió reps opcions suaus i el consell de consultar un professional. Fa servir la mateixa quota d'IA que l'agenda i la rutina: 5 vegades gratis i 60 al mes amb Premium.",
    faq_q_sport_workout_ai: "Com creo un pla d'entrenament amb IA?",
    workout_ai_add: "Afegir a la meva taula",
    workout_ai_again: "Una altra proposta",
