    workout_ai_when_morning: "Matí",
    workout_ai_when_noon: "Migdia",
    workout_ai_when_ph: "p. ex. després de la feina, o 17:30",
    workout_ai_working: "Creant el pla…",
    faq_a_sport_workout_jar: "Cada tipus d'entrenament té la seva estrella de color: córrer rosa, caminar verd, natació blau, etc. Cada entrenament que registres aquesta setmana, des de la taula o a part, deixa caure la seva estrella al pot de dalt d'Els meus entrenaments, i el pot es va omplint fins al teu objectiu setmanal (toca'l per canviar l'objectiu). Quan arribes a l'objectiu, el pot brilla. El pot petit del costat compta quantes setmanes seguides l'has omplert.",
    faq_q_sport_workout_jar: "Què són les estrelles de colors i el pot a Els meus entrenaments?",
    faq_a_sport_workout_gcal: "Sí: a ⋯ → Google Calendar (un cop connectat Google Calendar a Configuració). Cada entrenament amb hora es converteix en un esdeveniment que es repeteix cada setmana els seus dies, i els canvis a l'aplicació l'actualitzen. Els recordatoris arriben només des de l'aplicació, així que Google no n'afegeix de propis, i els entrenaments no apareixen mai dues vegades a l'aplicació. Tocant-lo de nou es treuen de Google Calendar només els entrenaments.",
    faq_q_sport_workout_gcal: "Els meus entrenaments poden aparèixer a Google Calendar?",
    workout_gcal_btn: "Google Calendar",
    workout_gcal_error: "No s'ha pogut actualitzar Google Calendar: es tornarà a provar al proper canvi",
    workout_gcal_not_connected: "Primer connecta Google Calendar a Configuració",
    workout_gcal_off_toast: "Els entrenaments s'han tret de Google Calendar",
    workout_gcal_on_toast: "Els teus entrenaments són a Google Calendar",
    faq_a_sport_workout_reminder: "Sí: en un entrenament, Recordatori: 10 minuts, 30 minuts o una hora abans, o un temps personalitzat (l'entrenament necessita una hora). Sona com els altres recordatoris, una vegada i en un sol lloc: a l'aplicació si és oberta, si no al mòbil. \"Fet\" registra l'entrenament a l'historial, i \"Encara no\" el recorda de nou d'aquí a 5 minuts.",
    faq_q_sport_workout_reminder: "Puc rebre un recordatori abans d'un entrenament?",
    workout_reminder_30min: "30 minuts abans",
    workout_reminder_label: "Recordatori",
    workout_reminder_need_time: "Afegeix una hora per rebre un recordatori",
    faq_a_sport_workout_share: "A ⋯ → Comparteix, la setmana es converteix en una imatge de vidre amb els colors del teu tema i un enllaç discret a l'aplicació (al mòbil va directament al menú de compartir; a l'ordinador la imatge es desa). ⋯ → PDF per imprimir obre una pàgina neta amb tota la setmana i una casella per marcar al costat de cada entrenament i exercici: tria \"Desa com a PDF\" o imprimeix-la. El pla també surt a l'informe de dades de Configuració, a la part d'Esport.",
    faq_q_sport_workout_share: "Com comparteixo o imprimeixo la meva setmana d'entrenament?",
    share_image_saved: "La imatge s'ha desat: la pots adjuntar",
    share_save_image: "Desa la imatge",
    workout_pdf_btn: "PDF per imprimir",
    workout_share_btn: "Comparteix",
    faq_a_sport_workout_board: "A ⋯ → Tauler setmanal cada dia és una columna: arrossega un entrenament a un altre dia (al mòbil, mantén premut primer). En un entrenament, \"També a La Meva Rutina\" el posa a la teva rutina a la seva hora i dies, i els canvis es mantenen sincronitzats en tots dos sentits; des d'un element de La Meva Rutina, \"Afegeix als meus entrenaments\" fa el contrari. Un ✓ en qualsevol dels dos compta en tots dos, i a El Meu Dia apareix només una vegada: a l'etiqueta del costat de l'aigua.",
    faq_q_sport_workout_board: "Com moc un entrenament a un altre dia i l'enllaço amb La Meva Rutina?",
    routine_in_workouts_btn: "Obre als meus entrenaments",
    routine_to_workout_btn: "Afegeix als meus entrenaments",
    routine_to_workout_done: "Afegit als meus entrenaments 💪",
    workout_delete_confirm_routine: "Es traurà del pla i de La Meva Rutina. Els entrenaments ja registrats a l'historial es queden.",
    workout_moved: "Mogut a {day}",
    workout_routine_need_time: "Afegeix una hora per posar-lo a La Meva Rutina",
    workout_routine_toggle: "També a La Meva Rutina",
    workout_view_board: "Tauler setmanal",
    workout_view_timeline: "Línia de temps",
    faq_a_sport_workout_plan: "A Seguiment d'Entrenaments, a \"Els meus entrenaments\": + Entrenament – tipus, dies, hora, durada, intensitat i lloc (també \"Altres\"). Els entrenaments de força, funcionals i de natació poden tenir una llista d'exercicis, i Descans marca un dia de descans. També pots començar amb un pla fet. L'entrenament d'avui surt en gran, amb tota la setmana a sota; ✓ el registra a l'historial d'entrenaments amb la seva intensitat. A ⋯ fixes un objectiu setmanal (entrenaments o minuts): cada entrenament que fas deixa caure la seva estrella al pot.",
    faq_a_sport_workout_today: "A El Meu Dia, al costat de l'aigua, una petita etiqueta mostra l'entrenament d'avui: en tocar-la s'obren els detalls, ✓ i ▶. ▶ engega un temporitzador que continua a l'etiqueta de la pantalla d'inici, i \"Acaba\" registra l'entrenament amb el temps real. Si el repte \"Dues setmanes de moviment\" de New Me està en marxa, un entrenament registrat hi compta sol.",
    faq_q_sport_workout_plan: "Com planifico la meva setmana d'entrenament?",
    faq_q_sport_workout_today: "On veig l'entrenament d'avui i com funciona el temporitzador?",
