    faq_a_new_me_magic_themes: "Cinc temes brillants inclosos a New Me: Bosc encantat, Pols d'estels, Fada de les roses, Aurora màgica i Capvespre daurat. Tria'n un dins de New Me (⚙️ Configuració > Colors) o a Configuració > Aparença i pantalla, i un pinzell de purpurina pinta la pantalla amb aquest tema. Un tema màgic afegeix purpurina a tota l'app i a cada toc. Pots tornar a qualsevol altre tema quan vulguis.",
