    apptour_focus_text: "Tot s'aparta menys l'única cosa d'ara, amb un ✓ gran. Després apareix la següent.",
    apptour_m_presets_text: "Els teus àpats desats en un sol lloc: cerca, usats fa poc, per hora del dia – i ＋ n'afegeix un a avui.",
    apptour_night_text: "🌙 enfosqueix tota l'app; ☀️ torna el dia.",
    apptour_noteline_text: "Escriu i toca ➤: es desa a les teves notes. 📝 al començament canvia a 🛒 la compra o a 🍎 un àpat desat.",
    apptour_search_text: "Notes, compra, calendari, receptes, quaderns, objectius, taules i llibres: una sola cerca ho troba tot.",
    faq_a_new_me_ai_menu: "Abans del menú, el qüestionari pregunta quins àpats fas i quan (2 àpats + un berenar, 2 àpats + un sopar lleuger, o tots dos), si menges alguna cosa petita al vespre i a quina hora, què no menges i com prens el cafè o el te. Després la IA crea 3 opcions per a cada àpat – cadascuna de la mida de la seva part del dia, així que el dia continua sumant exactament 1.300 o 1.500 – i idees de begudes, que es desen com les teves begudes fixes. Tria fins a 2 preferides per àpat; les opcions del menú original són just a sota, i a 🔄 Canviar apareixen després del teu menú personal. 🔄 Altres opcions crea una tanda nova (3 vegades per qüestionari). Per canviar les respostes o crear un menú nou quan vulguis: ⚙️ Configuració → ✨ Menú personal (IA).",
    faq_q_new_me_ai_menu: "Com funciona el menú personal de New Me?",
