    apptour_s_menu_text: "Aquí hi ha tot el que pots ajustar, en cinc grups. Obrim-los 👇",
    apptour_skip_part: "Salta aquesta part",
    apptour_start: "Començar el tour",
    nm_sales_premium: "Inclou tot Premium",
    nm_unlock_premium: "I tot Premium també s'ha desbloquejat.",
    settings_sub_status_newme: "Premium està inclòs al teu New Me.",
    room_back_to_shelf: "Al prestatge",
    faq_a_new_me_day_total: "Cada dia suma exactament el pla: els àpats, unes 150 calories per a cafè i begudes durant el dia, i el que s'hagi triat per al vespre – alguna cosa petita per menjar o alguna cosa per beure. Per al vespre, tria'n fins a 3 que t'agradin (per exemple un plàtan, un iogurt o 2 quadrets de xocolata negra; o una infusió d'herbes, te amb una mica de llet o llet calenta), i les seves calories es treuen dels àpats. Cada tria s'equilibra sola: una opció més petita o més gran, un àpat tret, l'esmorzar petit i l'àpat petit que l'acompanya, o el vespre – la diferència se suma als àpats o se'n resta, a cadascun segons la seva mida, i sota cada àpat hi diu quant (+ o −) i què afegir o treure. Un àpat ja marcat es queda com es va registrar. Al qüestionari, cada àpat mostra el seu ajust, i un quadre petit mostra àpats, begudes, el vespre i el total. Et ve de gust una altra cosa aquell dia? Mantén el total en les mateixes calories o menys.",
    faq_q_new_me_day_total: "Com suma un dia de New Me exactament 1.300 / 1.500, i on compten les begudes?",
