    nm_less_ideas_l: "una llesca de pa i una cullerada de tahina menys, o la meitat dels hidrats",
    nm_less_ideas_m: "una llesca de pa menys, o una cullerada menys de tahina",
    nm_less_ideas_s: "una culleradeta menys d'oli o tahina",
    nm_less_line: "{n} calories en aquest àpat, perquè el dia sumi {plan} – per exemple {ideas}",
    nm_less_line_late: "{n} calories en aquest àpat, per a alguna cosa petita a les {time} – per exemple {ideas}",
    nm_swap_balanced: "{n} calories repartides entre els àpats, perquè el dia sumi {plan}",
    books_quotes_chip: "Cites",
    faq_a_book_quotes: "Al prestatge de l'habitació secreta (Cites), o amb la petita etiqueta 💬 Cites del Racó de lectura: és la mateixa llista. Toca \"+ Cita\", escriu la frase i tria el llibre del teu Racó de lectura, o escriu un altre títol amb \"✏️ Altres\"; l'autor és opcional. ✏️ edita una cita i 🗑️ l'elimina. Les cites són punts de llibre que es llisquen: 🎨 a dalt canvia a fotos o a un mur de targetes.",
    faq_a_room_wish_jar: "Al prestatge de l'habitació secreta hi ha un pot de vidre per als somnis. Toca el potet del prestatge de dalt (o Prestatge > El pot dels desitjos) i escriu com voldries que fos la teva vida: tan boig com vulguis, sense bé ni malament. Cada desig es plega en un paperet i cau al pot. «Treu un paperet» n'obre un a l'atzar, i cada paperet també es pot obrir sol. A partir de la segona vegada que obres el mateix desig, el pots convertir en un objectiu i dividir-lo en petits passos. Un cop per setmana apareix amb suavitat un paperet amb un dels teus desitjos: sense pressió, només un recordatori de cap on vas.",
    faq_q_book_quotes: "On guardo les cites de llibres que he estimat?",
    faq_q_room_wish_jar: "Què és el pot dels desitjos de l'habitació secreta?",
