    room_wish_to_goal: "🎯 Converteix-lo en un objectiu, a petits passos",
    room_wish_written: "Escrit el {date}",
    faq_a_saved_meals_page: "Els àpats desats tenen una pàgina pròpia: Nutrició i Mesures > ⭐ Àpats desats (o ⭐ al menú). La cerca de dalt troba un àpat pel nom o per un ingredient, \"Fets servir fa poc\" mostra el que has afegit darrerament, i les pestanyes (Esmorzar, Dinar, Sopar, Sopes…) mostren cada moment del dia. \"+ Avui\" afegeix un àpat al Registre Diari d'Àpats d'avui, al següent espai lliure. Toca un àpat per editar-lo o eliminar-lo, i ＋ a dalt n'afegeix un de nou.",
    faq_q_saved_meals_page: "On trobo i gestiono els meus àpats desats?",
