    presets_tab_soup: "Sopes",
    presets_tab_sweet: "Llaminadures",
    faq_a_notes_sticky_look: "Les notes són una llista curta de targetes de vidre: 🎨 a dalt de Notes canvia l'aspecte de totes les Notes – la llista, els botons dels dies de dalt i la finestra on s'escriu una nota (vidre, llista neta, fitxes o cinta washi). Una nota que s'arrossega manté exactament el seu aspecte i el seu color. Toca el text d'una nota per obrir-la: allà la pots editar, canviar-ne els colors i veure quan es va escriure per última vegada. Toca ○ quan estigui feta, i × la mou a l'arxiu (🗑️ al final de la llista la recupera). Arrossega-la per ⠿ per canviar l'ordre, a sota de «Més tard» o a un dia de dalt. ! marca una nota com a urgent – puja suaument fins a les primeres files amb una petita etiqueta «Urgent»; un altre toc la treu.",
    faq_q_notes_sticky_look: "Com obro, edito o trec una nota?",
    note_to_archive_btn: "Mou a l'arxiu",
    faq_a_routine_clash: "Si a aquella hora, els mateixos dies, ja hi ha un element, apareixen dues opcions: «Substituir» – el nou element es queda aquella hora i tries una altra hora per al que hi havia (en editar un element existent, se'n proposa l'hora anterior, així que simplement s'intercanvien), o «Tots dos» – tots dos es queden a la mateixa hora, l'un sota l'altre. Si els dies són diferents (per exemple, un de diumenge a dijous i l'altre el divendres), no es pregunta res.",
    faq_q_routine_clash: "Què passa si poso un element de la rutina a una hora que ja està ocupada?",
    routine_clash_both: "✌️ Tots dos – tots dos a les {time}",
    routine_clash_move_btn: "Moure i desar",
    routine_clash_move_to: "A quina hora es mou «{title}»?",
    routine_clash_replace: "🔄 Substituir – i moure «{title}» a una altra hora",
    routine_clash_title: "A les {time} ja hi ha: {title}",
    faq_a_new_me_coffee: "Sota el menú d'avui hi ha un resum breu: quantes calories sumen tots els àpats del dia, quant queda per a cafè i begudes, i botons per al cafè i les begudes triats – amb un toc s'afegeix a Begudes. A «Tria'n fins a 3 que t'agradin», sota els botons (i al qüestionari), tries què hi surt: aigua / aigua amb gas, infusió d'herbes, un refresc light, sol / americano (~5), te amb una mica de llet (~25), cafè amb aigua i fins a 100 ml de llet o beguda vegetal (~50), xocolata calenta lleugera, llet calenta o cafè normal / amb llet (~120).",
    faq_q_new_me_coffee: "On afegeixo el cafè, i com sé quant em queda del dia?",
