    nm_late_room_line: "Alguna cosa petita abans de dormir · queden ~{n} kcal avui",
    faq_a_recipe_examples: "Sota les teves receptes hi ha receptes d'exemple: esmorzars, amanides, sopes, plats principals, guarnicions, pica-pica, postres i plats vegans, cadascuna amb el temps de preparació, les calories per ració i quants grams pesa una ració. Toca una recepta per obrir-la, i «Desar a Les Meves Receptes» en crea la teva pròpia còpia, que pots editar. Les etiquetes de categoria filtren, i tornar a tocar la mateixa etiqueta ho mostra tot.",
    faq_a_recipe_grams: "Dins d'una recepta, al costat de les calories, hi diu «1 ració ≈ X g». A les teves receptes, omple «Grams per ració» (i el temps de preparació, si vols) al formulari de la recepta: tots dos són opcionals, i el temps apareix a la franja de color de la recepta.",
