    recipes_examples_title: "Receptes d'exemple",
    faq_a_recipe_scan_multi: "Sí. A «Afegir Recepta», toca 📷 i tria una foto o diverses (fins a 6; també serveix un PDF). Cadascuna apareix en una llista curta on tries què hi ha: Tot, Ingredients o Preparació, i «➕ Una altra foto» n'afegeix més. Després toca «✨ Escanejar la recepta»: la IA ho uneix tot en una sola recepta, en ordre i sense línies repetides, i compta com un sol escaneig. Diverses fotos triades des de 📷 Foto a l'assistent d'IA també s'obren aquí.",
    faq_q_recipe_scan_multi: "Puc escanejar una recepta a partir de diverses fotos, per exemple els ingredients i els passos per separat, o dues pàgines?",
