    faq_a_note_written_at: "Toca el text de la nota per obrir-la. A dins, sota el text, apareix quan es va escriure per última vegada, amb la data i l'hora exactes. Només un canvi en el text l'actualitza: arxivar-la i restaurar-la, marcar-la ✓, els colors o moure-la no ho canvien.",
    faq_q_note_written_at: "Com veig quan vaig escriure una nota?",
    note_written_at: "Escrita per última vegada: {date}",
    faq_a_new_me_month: "A la motxilla màgica → Calendari mensual: cada dia té un color segons quants àpats s'han marcat, les fletxes ‹ › passen d'un mes a l'altre, i sota el calendari hi ha la mitjana diària de calories del mes. En tocar un dia es veu quants àpats s'hi han marcat i quantes calories s'hi han menjat.",
    faq_q_new_me_month: "On puc veure el mes enrere i la mitjana de calories a New Me?",
    nm_month_avg: "Mitjana del mes: {kcal} calories al dia · dies amb registre: {n}",
    nm_month_day_empty: "Aquest dia no s'ha registrat res.",
    nm_month_day_line: "Àpats marcats: {checks} · calories: {kcal}",
    nm_extra_line_small: "{n} calories per a aquest àpat, de l'esmorzar petit – per exemple {ideas}",
    faq_a_new_me_small_breakfast: "Un esmorzar lleuger (unes 170 kcal): una pita d'espelta (fins a 100 kcal) amb crema per untar o formatge, més una verdura – tria'n fins a 3 que t'agradin, per exemple 1 culleradeta de crema de xocolata, 1 culleradeta de crema de cacauet o una llesca de formatge semicurat (fins al 22%). Com que és petit, l'acompanya «I un àpat petit» a una altra hora (una hora i mitja després, per exemple 11:30 → 13:00 – es pot triar qualsevol altra hora): una altra pita amb crema, iogurt proteic i fruita, galetes d'arròs i formatge, cereals amb llet o mitja pita i ous – fins a unes 200 kcal, amb el seu propi ✓. El que encara queda es reparteix entre els altres àpats, i cada àpat mostra quant se li ha afegit, així que el total del dia queda com al pla. Pots triar-lo al qüestionari o canviar-hi només per avui amb 🔄 – per exemple, quan esmorzes tard.",
    faq_q_new_me_small_breakfast: "Què és l'«esmorzar petit» del menú de New Me?",
