    weather_sky_storm: "Tempesta",
    faq_a_ai_icon: "Sí, a Configuració > Aparença i pantalla. La bombolla suau és la predeterminada, i amb Premium també pots triar un cervell flotant o un robot.",
    faq_a_new_me_favorites: "Sí. Al qüestionari (i en repetir-lo des de la configuració) pots triar fins a 2 opcions per a cada àpat. La primera apareix al menú, amb una línia «o» a sota per a la segona: en tocar-la canvies a aquella només per avui. I si l'esmorzar no s'ha menjat a temps, «⏰ Més tard» el passa a més tard durant el dia, sense canviar les calories.",
    faq_a_theme_mode: "Alguns temes especials llueixen més en fosc – Aquarel·la, Aurora boreal, Barbie i els dos temes de purpurina –, així que triar-ne un passa l'app al mode fosc, i triar qualsevol altre tema (també el coet) la passa al clar. Negre i Gris fosc es queden foscos. Sempre pots canviar-ho després amb 🌙 al menú o amb Mode Clar a la configuració.",
    faq_a_water_month: "Al seguiment de l'aigua. Cada entrada del registre d'avui mostra l'hora en què es va afegir, i \"Taula mensual\" obre tot el mes: cada dia mostra quants litres s'han begut (✓ quan s'ha arribat a l'objectiu diari), i en tocar un dia apareixen les seves entrades amb les hores.",
