    dev_sim_panel_title: "PM – només per a tu",
    faq_a_new_me_weight_optional: "No. Tant el pes actual com el pes objectiu del qüestionari són opcionals. Si més endavant s'afegeix una pesada (⚖️ Pes a «El meu camí» de New Me, o al registre de pes), el progrés es compta des de la primera.",
    faq_q_new_me_weight_optional: "Cal escriure el pes a New Me?",
    nm_unlock_desc: "El menú, els reptes i el camí ja estan a punt: pas a pas, de la mà.",
    nm_unlock_title: "New Me desbloquejat!",
    room_reveal_star: "Una estrella nova s'ha encès al telescopi del terrat ✨",
    faq_a_room_records: "El tocadiscos és a l'habitació des del principi, damunt la soca al costat de la butaca. Els seus discos obren a YouTube els videoclips oficials de grans èxits dels darrers anys, i a sota hi ha cinc melodies tranquil·les que sonen aquí mateix a l'habitació: el disc gira mentre sonen, i «⏹ Atura» para la música.",
    faq_a_room_roof_gifts: "Arriben amb la 8a clau. Tocar el telescopi permet mirar-hi a través: el cel nocturn de ben a prop (arrossega, o fes servir les fletxes, per mirar al voltant), i els teus reptes acabats hi dibuixen una constel·lació, una estrella per cada repte; en tocar una estrella es veu quin era. Tocar el cofret l'obre (de moment és buit) i un altre toc el tanca.",
    faq_q_room_records: "Què hi ha al tocadiscos de l'habitació secreta?",
    faq_q_room_roof_gifts: "Què són el telescopi i el cofre del terrat?",
    room_chest_letter: "Una carteta per a tu",
    room_chest_letter_1: "Cada petit pas del camí va ser real, i tots compten.",
    room_chest_letter_2: "Tractar-se amb afecte forma part del camí, no n'és una pausa.",
    room_chest_letter_3: "Hi ha dies més lleugers i dies més feixucs. Ser-hi en tots dos és la veritable força.",
    room_chest_letter_4: "Descansar està permès. Descansar també és avançar.",
