    dev_sim_locked_toast: "🔒 Bloquejat – així es veu abans de comprar",
    faq_a_new_me_preview: "Sí. La pàgina de New Me comença amb un vídeo curt del que passa a dins: el qüestionari, els llums del passadís, la motxilla, els reptes i les claus. A sota hi ha tot el que inclou, una ullada a un dia i respostes breus.",
    faq_q_new_me_preview: "Puc veure New Me abans de comprar-lo?",
