    ai_chat_food_edit: "✏️ Corregir calories / proteïna",
    ai_chat_food_invalid: "Les calories han de ser un nombre més gran que 0",
    ai_chat_food_updated: "Actualitzat:",
    faq_a_ai_chat_food_fix: "Sí. Sota la resposta al xat, toca ✏️ Corregir calories / proteïna, canvia els números i toca Desar. Només canvia el que s'acaba d'afegir – encara que s'hagi sumat a un berenar que ja hi era. La IA es pot equivocar, així que val la pena revisar-ho.",
    faq_a_new_me_home_btn: "Amb New Me, un petit 💎 al costat del mode concentració, a dalt de la pantalla d'inici, obre el menú d'avui. Els àpats d'avui també surten a El Meu Dia, cadascun amb la seva ✓.",
    faq_a_routine_item_days: "Sí. Toca l'element a La Meva Rutina i tria'n els dies a 📅 Dies – per exemple, només de dilluns a divendres. Els altres dies no surt a El Meu Dia i no té ✓; a La Meva Rutina s'hi queda, més pàl·lid, amb els dies al costat. La targeta que pregunta per un element després de 3 dies sense ✓ només compta els dies d'aquest element.",
    faq_q_ai_chat_food_fix: "Puc corregir les calories o la proteïna després que l'assistent registri menjar?",
    faq_q_new_me_home_btn: "On és New Me a la pantalla d'inici?",
    faq_q_routine_item_days: "Un element de La Meva Rutina pot ser només alguns dies?",
    routine_item_days_label: "📅 Dies",
    home_note_meal_ph: "Cerca un àpat desat…",
    menu_quick_search: "Cerca ràpida",
    nm_times_hint: "Consell: pots posar l'hora més tardana en què acostumes a fer cada àpat; per exemple, les 9:00 si sovint menges cap a les 8.",
    room_game_marquee: "De camí – atura't i gaudeix",
    room_sand_erase_aria: "Frega per esborrar el que hi ha escrit",
    faq_a_home_note_line: "Escriu a la línia del mig de la pantalla d'inici i toca ➤ (o Retorn): es desa a Notes. Toca 📝 al principi de la línia i es converteix en 🛒: llavors el que escriguis va a la Llista de Compres. Toca-hi un cop més per a 🍎: escriu unes lletres, apareixen els teus àpats desats que hi coincideixen, i un toc en registra un als àpats d'avui. Amb 🎤 pots simplement dir-ho.",
    faq_a_night_mode: "Obre el menú ☰ i toca 🌙 a dalt: tota l'app es torna fosca. ☀️ al mateix lloc torna el dia. També és a Configuració, a Mode Clar.",
    faq_q_home_note_line: "Com escric una nota ràpida des de la pantalla d'inici?",
    faq_q_night_mode: "Com passo al mode nit?",
    menu_day_mode: "Mode dia",
    menu_night_mode: "Mode nit",
    faq_a_secret_room_yoga: "Al final del camí del bosc hi ha un portal lluminós i, al darrere, al costat d'una cascada, les criatures del bosc – Lumi, Puffi, Nixie i Sparklet – seuen damunt les seves estoretes en mig cercle, i la Flora, la mestra de ioga, seu davant d'elles a l'única estoreta que hi ha damunt la pedra. Toca la Flora: obre els ulls, tot s'apropa i la conversa comença a poc a poc, amb temps per llegir – la Flora pregunta com està tothom, cada criatura respon en nom propi (amb un dibuixet de qui parla al costat de cada línia) i després et pregunta com et sents amb les persones properes. La conversa continua segons les teves respostes – gent bona, algú amb qui costa o una mica de solitud. Cada camí acaba amb una petita missió (pot anar directament a El Meu Dia; quan la missió és escriure alguna cosa, hi ha un lloc per escriure-la, i es desa al diari màgic) i una postura amb tres respiracions compartides. ↩ torna un pas enrere i ✦ comença una conversa nova. La clau següent obre la cascada: en seure a la pedra tot desapareix i només queda el so de l'aigua. En treure el cap sobre la bassa, una pregunta puja de l'aigua –què faria avui el teu jo de veritat?– i la resposta es converteix en una petita tasca a El Meu Dia. És un moment amable, no un substitut de parlar amb un professional.",
    faq_q_secret_room_yoga: "Què passa al ioga del bosc?",
    room_back_to_forest: "Tornar al camí",
    room_back_to_yoga: "Tornar al ioga",
    room_item_waterfall: "La cascada",
    room_waterfall_pool_aria: "Tocar l'aigua",
    room_waterfall_rock_aria: "Seure a la roca",
    room_yoga_guide_aria: "Parlar amb la Flora",
    yg_g_alone: "Gràcies per compartir-ho. A tothom li passa de vegades.",
    yg_g_alone_q: "Què et faria sentir bé, encara que sigui una mica?",
    yg_g_critic: "Una crítica pot fer mal molt de temps. Parla d'un moment, no de tota la persona.",
    yg_g_end: "Gràcies per aquest moment al cercle. Pots tornar quan vulguis.",
    yg_g_gate: "Es pot posar un límit. Un límit no és un mur: és una porta.",
    yg_g_good: "Que bonic 💛 Qui t'ha fet bé aquesta setmana?",
    yg_g_good_msg: "Val la pena dir-ho a la gent bona. Un petit gràcies els pot alegrar tot el dia.",
    yg_g_hard: "Gràcies per dir-ho. Què és el que et pesa més?",
    yg_g_listen: "Que no t'escoltin cansa. La teva veu compta, encara que sigui fluixeta.",
    yg_g_new: "La gent nova comença amb un petit hola. Una classe, una passejada, un grup: un pas.",
    yg_g_old: "Algú que ja et coneix és un lloc càlid. N'hi ha prou amb un missatge curt.",
    yg_g_start: "I ara et toca a tu 🌿 Com et sents darrerament amb les persones properes?",
