    nm_time_hour: "Hora",
    nm_time_minutes: "Minuts",
    routine_time_taken: "Ja hi ha alguna cosa a aquesta hora: {title}",
    faq_a_new_me_times: "Al qüestionari de l'inici i, en qualsevol moment, a la configuració de New Me → «Hores dels àpats». Si la teva rutina ja té hores d'àpats, s'agafen d'allà – i els àpats de la rutina es poden amagar, amb els àpats de New Me al seu lloc. Si no, tries quants àpats al dia (2 àpats + un berenar / 2 àpats + un sopar lleuger / 2 àpats + un berenar + un sopar lleuger) i quan és cadascun. Amb «2 àpats + un berenar» són el dinar a les 11:30, el berenar a les 16:00 i el sopar a les 19:00 (es poden canviar tots). Aquestes són les hores dels teus àpats a tot arreu: al passadís, a El Meu Dia, a La Meva Rutina i als recordatoris. Triïs el que triïs, les calories del dia no canvien: el que es treu es reparteix entre els altres àpats.",
    faq_q_new_me_times: "Com fixo les hores dels àpats a New Me?",
    nm_times_count: "Quants àpats al dia?",
    nm_times_from_routine: "Sí, agafa-les de la meva rutina",
    nm_times_hide: "Amaga els àpats de la meva rutina i mostra al seu lloc els àpats de New Me",
    nm_times_later: "Més tard",
    nm_times_manual: "No, tria-les aquí",
    nm_times_none_found: "La teva rutina encara no té àpats: tria aquí quants i quan.",
    nm_times_q: "La teva rutina té hores fixes per menjar?",
    nm_times_saved: "Hores dels àpats desades",
    nm_times_title: "Hores dels àpats",
    faq_a_routine_exact_time: "Sí. Quan descrius una rutina a la IA amb una hora exacta (com \"16:10 trading\"), es desa exactament així, sense arrodonir a l'hora en punt. Tot el que hi ha escrit a la rutina apareix sempre al tauler, encara que aquella hora no estigui triada a la configuració d'hores, i treure una hora que té alguna cosa escrita demana confirmació primer. També pots canviar una hora a mà: toca l'hora a la finestra de l'element i tria l'hora i els minuts.",
    faq_q_routine_exact_time: "La meva rutina pot tenir una hora exacta, com 16:10?",
    room_item_sand: "Escriure a la sorra",
    room_item_yoga: "Ioga al bosc",
