    room_song_4: "Gymnopédie núm. 1 · Satie",
    room_song_5: "Greensleeves · tradicional",
    room_vinyl_stop: "⏹ Atura",
    routine_hour_remove_text: "El que hi ha escrit a aquesta hora s'esborrarà de la rutina: {title}",
    routine_hour_remove_title: "Treure {time}?",
    faq_a_routine_ai: "A La Meva Rutina, obre ⚙️ (o ➕) i toca \"Una rutina nova amb IA\": descriu la rutina amb paraules senzilles – per exemple \"llevar-se a les 7, gimnàs a les 8, feina fins a les 17\" – i la IA crea una pestanya nova amb les hores i les tasques. Si el text diu quins dies (\"entre setmana\"), la pestanya s'obre aquests dies, i rutines diferents per a dies diferents es converteixen en pestanyes separades. Després tot es pot editar com sempre.",
    faq_a_routine_daysoff: "A La Meva Rutina, toca ➕ i després \"Dies lliures\": tria els dies (per exemple dissabte i diumenge) i quina rutina hi ha – sense horari (queda lliure), la teva pròpia rutina, o explica a la IA què fas perquè la munti. Els dies lliures tenen una pestanya pròpia, i aquests dies La Meva Rutina i El Meu Dia només mostren aquesta pestanya.",
    faq_q_routine_ai: "Com creo una rutina amb IA?",
    faq_q_routine_daysoff: "Com marco dies lliures a La Meva Rutina?",
