    faq_a_secret_room_diary: "Només tu. Les pàgines del diari es desen al teu compte, així que són a tots els dispositius i ningú més les pot veure. L'obre el diari màgic de l'escriptori de l'habitació secreta, i també el diari del racó de la música. Sota la pàgina nova hi ha una taula mensual plegada: un punt marca cada dia que té una pàgina, i tocar un dia n'obre les pàgines; allà també es pot esborrar una pàgina. Quan el diari ja és obert, també es pot afegir al menú principal, amb l'interruptor del mateix diari o a la configuració de New Me.",
    faq_a_secret_room_places: "Cada entrada del portal del bosc s'obre amb la seva clau. Al darrere: el porxo davant del mar (damunt la taula petita, la llàntia d'Aladí – un toc i un esperit del bosc en surt dins una boira màgica, fa voltes i comença una conversa sobre el teu desig – mira «Què fa el geni de la llàntia?»), la guitarra i el diari (la guitarra fa sonar una melodia curta i tranquil·la i s'atura sola, i cadascun dels tres discos que pengen de l'arbre fa sonar la seva pròpia melodia màgica – un altre toc l'atura – i el diari de damunt la soca és per escriure), la sala de respirar (un llac tranquil a la posta de sol; sobre l'aigua flota un fanalet de lotus: toca'l, escriu un desig, i s'allunya amb ell, lluny, enrere dins el llac; amb la vareta màgica pots escriure a la sorra el que vols deixar anar, i es queda fins que ho esborres amb el dit) i el camí del bosc (s'obre de nit, i tocar els fanals el fa passar a dia; de la branca gran penja un gronxador màgic, el banc és per seure, i tocar el rètol l'apropa: un tauler amb sis preguntes petites per marcar). En una entrada tancada es veu quantes claus falten. Al final del camí, un portal lluminós porta al ioga al costat de la cascada i, d'allà, a la mateixa cascada.",
    faq_q_secret_room_diary: "Qui veu el diari?",
    faq_q_secret_room_places: "Què hi ha darrere de les portes del passadís?",
