    ai_chat_working_table: "Un moment, creant la taula…",
    dev_weather_preview_label: "Previsualització – només al teu compte:",
    faq_a_ai_chat: "Toca la bombolla i s'obre un xat. Tria què vols fer – alguna cosa per al calendari, el que has menjat, una foto d'una recepta o una taula nova – o simplement escriu, i l'assistent ho entén sol. Per al calendari pots triar un cop, cada setmana o cada dia. La resposta arriba al xat, i des d'allà pots continuar amb una altra cosa o obrir el calendari / el que has menjat.",
    faq_a_new_me_hall: "New Me s'obre al portal d'un bosc màgic, i cada entrada és un lloc: la porta rodona de l'arbre gegant mena a l'habitació secreta, el tronc buit – al porxo davant del mar, la caseta-bolet – a la guitarra i el diari, l'arc petit de salze – a la sala de respirar, l'arc gran de salze – al camí del bosc, i l'arc de flors amb l'escala puja al terrat de les estrelles quan aquest s'obre. Una entrada tancada té un cadenat. Sobre el camí flota el teu personatge, Me, i al voltant, els botons del joc: la propera missió, el repte de la setmana, la motxilla màgica amb tot New Me, el mapa del món i les eines. Un toc a les claus de dalt explica com es guanyen les claus.",
    faq_a_new_me_routine_meals: "Quan hi ha àpats definits a New Me i La Meva Rutina també té àpats, New Me pregunta si cal amagar-los i mostrar al seu lloc els àpats de New Me – perquè res no surti dues vegades. Aleshores La Meva Rutina mostra els àpats de New Me a les seves hores, amb 💎 i un ✓; un toc al nom d'un àpat obre una finestra per triar-ne un altre o canviar-ne l'hora, allà mateix sobre la rutina. No s'esborra res: tornen des de ⚙️ Configuració de New Me → Àpats a la rutina, o desactivant «Sincronitzar amb New Me» al ⚙️ de La Meva Rutina. Sense un New Me actiu, tornen sols.",
    faq_a_room_computer: "És un petit xat que comença amb «Com va el teu dia fins ara?» – bé, atrafegat o difícil – i continua amb tu pas a pas, fins a una petita missió al final (que també pot anar directament a El Meu Dia). Les respostes es poden tocar o escriure lliurement – el que s'escriu es connecta amb la resposta més propera. «↩ Enrere» torna un pas per respondre d'una altra manera, i «Xat nou» torna a començar en qualsevol moment. Després d'un dia atrafegat o difícil pots tornar a l'ordinador més tard el mateix dia: «Torno a ser aquí...» continua la conversa. El llum verd de baix apaga i encén l'ordinador. Només es guarden les tries, només en aquest dispositiu i només fins al final del dia.",
    faq_q_ai_chat: "Com parlo amb l'assistent?",
    faq_q_new_me_hall: "Què és el passadís de New Me?",
    faq_q_new_me_routine_meals: "Per què La Meva Rutina mostra els àpats de New Me?",
