    dictation_btn_aria: "Parla i s'escriu",
    dictation_mic_denied: "El micròfon està bloquejat: permet-lo des del 🔒 al costat de l'adreça al navegador o a la configuració del telèfon",
    faq_a_dictation: "Sí: toca el micròfon 🎤 a la cantonada de la nota ràpida o d'una pàgina d'escriptura de la llibreta, i parla: les paraules s'escriuen mentre parles, en l'idioma de l'app. Torna-hi a tocar per aturar-ho. La primera vegada, el navegador demana permís per fer servir el micròfon. Funciona a Chrome / Android i a Safari a l'iPhone. A l'ordinador cal un micròfon i un navegador com Chrome, Edge o Safari; si falta alguna cosa, el missatge diu exactament què.",
    faq_q_dictation: "Puc parlar en lloc d'escriure?",
    faq_a_secret_room: "Una habitació només teva, dins de New Me: una casa dins d'un arbre gegant. Veus una paret cada vegada i et gires amb les fletxes (o lliscant). La primera clau arriba després d'un ✓ en un àpat en 3 dies diferents i obre la porta, i amb ella tota l'habitació: l'ordinador, el joc, el tocadiscos, el prestatge amb la biblioteca a dins i el gat. Després, cada repte acabat (també el repte de la setmana) dona una clau que obre el lloc següent: el terrat de les estrelles, el porxo davant del mar, la guitarra i el diari, la sala de respirar, el camí del bosc amb el ioga, la cascada i una sorpresa al terrat; i el 8è porta una ampolla del mar, amb la carta del passat a dins. Quan alguna cosa s'obre, una fletxa mostra el camí. La portelleta de la part baixa de la màquina del joc també s'obre: de moment l'armariet que hi ha al darrere és buit. Al terrat de les estrelles, una estrella que toques cau com una estrella fugaç, i el gat seu al coixí.",
