    settings_good_things_label: "«3 coses bones» al vespre",
    settings_weather_hint: "Pluja, núvols o neu al fons de la pantalla d'inici, segons el temps on ets. La teva ubicació aproximada es queda en aquest dispositiu i es consulta a través del nostre servidor amb MET Norway.",
    settings_weather_label: "El temps al cel de la pantalla d'inici",
    weather_failed: "Ara no s'ha pogut consultar el temps.",
    weather_location_denied: "No hi ha accés a la ubicació – permet-ho a la configuració del navegador i torna-ho a provar.",
    faq_a_home_focus: "Toca ◎ a la part de dalt de la pantalla d'inici: desapareix tot excepte l'única cosa d'ara – el que hi ha a aquesta hora, o el següent de la llista d'avui – amb una ✓ gran, i Notes Ràpides. Després de la ✓ apareix el següent. Toca 'Mode concentració ✕' a dalt perquè tot torni.",
    faq_a_home_search: "Obre el menú ☰: la cerca és just a dalt de tot. Escriu almenys 2 lletres: els resultats surten de les teves notes, llista de compres, calendari, receptes, llibretes (títols i text de les pàgines), objectius, taules i llibres, agrupats per tipus – toca'n un per anar-hi directament.",
    faq_a_my_day: "El Meu Dia reuneix el que abans eren Un Cop d'Ull a Avui i La Meva Rutina en una sola línia de temps. A la part de baix de la pantalla d'inici veus quant hi ha fet, què toca ara o després (amb una ✓ ràpida) i, al costat del títol, un got d'aigua amb +1. Toca-ho (o llisca cap amunt) per obrir tot el dia: a dalt el que no té hora, després tot per hores – tasques, esdeveniments i reunions del calendari, les franges fixes setmanals, la rutina d'avui, els petits passos dels teus objectius i els àpats de New Me – amb una línia per a l'ara. Filtra per Tasques, Rutina o Reunions i esdeveniments. Una ✓ aquí és la mateixa ✓ que a tot arreu (La Meva Rutina, Els Meus Objectius, el calendari) i obre una margarida al racó. 'Edita la rutina' obre La Meva Rutina (també és al menú), i '＋ Afegeix per avui' afegeix una tasca per avui. En tocar el títol \"El Meu Dia\" (o la barreta de dalt) es torna a tancar.",
    faq_q_home_focus: "Què és el mode concentració?",
    faq_q_home_search: "Com cerco a tota l'app?",
