    faq_a_new_me_tour: "Just després de comprar i omplir el qüestionari breu, un recorregut curt mostra el joc: la barra superior, la propera missió, les eines dels dos costats, el repte de la setmana, la motxilla màgica, el mapa del món, el teu personatge Me i la porta 1 a l'habitació secreta. Es pot tornar a veure en qualsevol moment des de ⚙️ Configuració > 🧭 Recorregut per New Me – allà també es pot canviar el nom complet del qüestionari. Abans de comprar, New Me mostra un 🔒 al menú, i en tocar-lo s'obre una pàgina amb tot el que inclou.",
