    nm_gift_intro: "Els {n} reptes, pas a pas. Això és el que esperava:",
    nm_gift_title: "El teu regal",
    faq_a_new_me_letter_gift: "En començar New Me (o més tard, a Reptes) es pot escriure una carta per a tu en el futur. Un cop segellada, no es pot llegir ni editar fins que s'obre: a l'ampolla del mar de l'habitació secreta, o al final dels 20 reptes – on també t'espera un regal.",
    faq_q_new_me_letter_gift: "Què és la carta del passat?",
    faq_a_new_me_challenges: "🏆 Reptes té 20 reptes: 10 de grans (com 5 dies sense sucre, una setmana sense hidrats de carboni o perdre 4 kg en un mes – dèficit calòric, entrenament i sense sucre cada dia) i 10 mini – petits hàbits durant una setmana, com el cafè amb canyella sense sucre. En triar un repte es pregunta quan començar: avui, demà, la setmana que ve o una altra data. Un repte gran i un mini repte poden anar alhora. El repte en curs apareix a dalt del menú i al Meu Dia, amb un ✓ per al dia. Cada setmana de repte porta un dia lliure (🍕) que no el trenca, i un dia sense marcar compta com a dia lliure – es pot marcar avui i també ahir. Alguns dies es marquen sols: un entrenament de 20 minuts a Seguiment d'Entrenaments, o els àpats del menú amb ✓. Cada repte té una ⓘ amb el que compta exactament (per exemple, la llista completa d'hidrats de carboni) – al mateix repte i al costat, al Meu Dia. A sota, 🌱 Creixement personal té 48 petits reptes d'una setmana (no compten per als 20) – mira «Què és el repte de la setmana?».",
    faq_q_new_me_challenges: "Com funcionen els reptes de New Me?",
    nm_letter_too_short: "Unes quantes paraules més 🙂",
    nm_letter_quiz_note: "Opcional – també es pot escriure més tard, a Reptes.",
    nm_letter_write: "✍️ Escriure la carta",
    nm_letter_sealed_line: "Segellada el {date} · s'obre després dels {n} reptes",
    nm_letter_sealed_toast: "Segellada ✉️ – ens veiem a la meta",
    nm_letter_seal_note: "Un cop segellada, la carta no es pot llegir ni editar fins que s'acabin tots els reptes.",
    nm_letter_seal: "✉️ Segellar la carta",
    nm_letter_ph: "On soc avui, on vull arribar, què em costa amb el menjar, què m'agradaria dir-me a la meta…",
    nm_letter_intro: "S'escriu ara i se segella – només s'obre després dels {n} reptes, per veure quant ha canviat tot des de llavors. On soc ara? Quins són els meus objectius i què em costa amb el menjar?",
