    nm_ch_start_title: "Quan comencem?",
    nm_ch_rule: "Un dia lliure per cada setmana de repte. Un dia sense marcar compta com a dia lliure – es pot marcar avui i també ahir. Un repte gran i un mini repte poden anar alhora.",
