    nm_ch_gift_locked: "Al final t'espera un regal",
    nm_ch_completed_label: "reptes completats",
    nm_tile_challenges: "Reptes",
    faq_a_workout_calories: "Sí. Cada entrenament rep una estimació de les calories cremades – segons el tipus, la durada i el teu darrer pes (en córrer i anar amb bici també segons la velocitat, si hi ha distància). Surt a la llista d'entrenaments i al resum mensual (Cremades), i se suma al pressupost de calories d'aquell dia: al Registre Diari d'Àpats, a Mètriques de Calories i Pes i a l'anell del New Me. És una estimació, per això porta ~.",
    faq_q_workout_calories: "Els entrenaments compten a les calories del dia?",
    faq_a_new_me_flexible_menu: "Sí. Al qüestionari i a la configuració es tria quants àpats al dia – 2 àpats + un berenar / 2 àpats + un sopar lleuger / 2 àpats + un berenar + un sopar lleuger – i ➖ a la targeta d'un àpat el treu (en queden almenys 3); «➕ Torna-hi» el recupera. En tots els casos les calories del dia no canvien: el que es treu es reparteix entre els altres àpats, i sota cada àpat s'indica quant s'hi ha afegit i què s'hi pot posar. ✏️ Edita en un àpat n'obre el text – canvia el que vulguis (p. ex. sense pa o amb un ou més) i la IA torna a calcular les calories i la proteïna. 🔄 Canvia ofereix opcions del menú, ⭐ Desats i ✨ Escriu-lo; cada canvi pot ser només per avui o des d'ara. I al final de «Tot el dia» hi ha ➕ Afegeix menjar – escriu el que s'ha menjat fora del menú i la IA ho calcula i ho suma a avui (✕ ho esborra).",
    faq_q_new_me_flexible_menu: "Puc canviar el nombre d'àpats a New Me, o menjar un àpat meu?",
    daily_calorie_mini_burn: "+🔥 {amount} dels entrenaments",
