    nm_remove_text: "Les seves ~{n} kcal es reparteixen entre els altres àpats, així que el total del dia no canvia. Es pot tornar a afegir en qualsevol moment.",
    nm_remove_title: "Treure {slot} del menú?",
    nm_remove_min: "Al menú hi queden almenys {n} àpats",
