    vision_focus_ribbon: "🎯 Objectiu del mes",
    vision_tagline: "Grans objectius, petits passos.",
    faq_a_app_tour: "El tour s'obre sol una vegada, la primera vegada que entres. Comença amb les seves parts – toca'n una per anar-hi directament – i després mostra totes les parts de l'app (la pantalla d'inici, l'assistent d'IA i cada element del menú) i els cinc grups de Configuració, cadascun amb una explicació breu, i treu el cap a dins d'alguns (per exemple, un camí d'objectiu d'exemple, la motxilla i Google Calendar). Continua avança, Enrere torna enrere, Salta aquesta part passa a la part següent i ✕ tanca el tour. Pots tornar-lo a veure quan vulguis des de Configuració > Ajuda i ús > Tour de l'app, i continuar on ho vas deixar. Continua i Enrere són sempre al mateix lloc, a baix de la pantalla, i a l'ordinador també funcionen les fletxes del teclat.",
    faq_q_app_tour: "Com es torna a veure el tour de l'app?",
    apptour_done_text: "Tens alguna pregunta? Ajuda i preguntes freqüents, a Configuració, ho respon tot, i aquest tour sempre és a Ajuda i ús.",
    apptour_done_title: "Això és tot! 🎉",
