    apptour_s_notifications_text: "Les notificacions de recordatori i el seu so. '⏰ Encara no' en un recordatori funciona com el botó de posposar d'un despertador: t'ho torna a recordar cada 5 minuts.",
    apptour_s_personalization_text: "País, àpats i berenars per dia, quan comença el teu mes financer i què es mostra a la pantalla d'inici.",
    apptour_s_appearance_text: "Idioma, mode clar o fosc, temes, tipus de lletra, color del text, accessibilitat i mida de l'app.",
