    apptour_m_myweek_text: "El calendari mensual, tasques setmanals recurrents amb recordatoris i tots els teus esdeveniments amb data. I una agenda de paper amb les reunions de la setmana 🤝.",
    apptour_m_newme_link: "Tot compta al Registre Diari d'Àpats i al Meu Dia; el pes es comparteix amb Mètriques de Calories i Pes.",
