    table_select_option_delete_confirm: "Aquesta opció s'utilitza en {count} files. Eliminar-la? Aquestes cel·les es buidaran.",
    table_select_option_delete_title: "Eliminar l'opció",
    faq_a_other_manual_option: "Sempre que tries d'una llista d'opcions, també hi ha '✏️ Altres': selecciona-la i escriu exactament el que necessites. En una taula amb una columna de selecció (per exemple 'Parentiu' en una taula de regals), toca la cel·la, tria '✏️ Altres', escriu el valor (per exemple 'Nebot') i toca Afegir: es desa com una nova opció d'aquesta columna, així que la propera vegada ja surt a la llista. La petita × al costat de cada opció d'aquesta llista elimina l'opció de la columna. En triar la icona d'una taula hi ha moltes icones (incloses notes adhesives de colors). Funciona igual a les categories d'àpats desats, les categories de receptes, les categories de despeses recurrents (es desa com una nova categoria personal) i les categories d'objectius a 'Els Meus Objectius'.",
    faq_q_other_manual_option: "L'opció que necessito no és a la llista, què puc fer?",
