    faq_a_receipts_total: "A la pantalla Factures / Rebuts, toca 🧮 'Total de tots els rebuts'. Tria des de quin any fins a quin any (per defecte, des del rebut més antic fins a aquest any), toca Calcula i apareixerà el total de les dues categories juntes - Despeses de la llar i Despeses de negoci - a més de quants rebuts hi ha i el total de cada categoria per separat.",
    faq_q_receipts_total: "Com es poden sumar tots els rebuts d'un període?",
    receipts_total_empty: "No hi ha rebuts en aquests anys.",
    receipts_total_invalid: "Introdueix un interval d'anys vàlid",
    receipts_total_count: "Rebuts: {count}",
    receipts_total_calc_btn: "Calcula",
    receipts_total_to_year: "Fins a l'any",
    receipts_total_from_year: "Des de l'any",
    receipts_total_title: "Total de tots els rebuts",
    receipts_total_tile: "Total de tots els rebuts",
    faq_a_quick_note_apple: "La 🍎 al costat de 📝 i 🛒 a la finestra de notes és una drecera per registrar ràpidament un dels teus àpats desats al Registre Diari d'Àpats d'avui. Està activada per defecte - si no la necessites, desactiva-la a Configuració > Personalització i calendari ('Mostrar la drecera 🍎 als àpats desats a la finestra de notes') i torna-la a activar allà quan vulguis.",
    faq_q_quick_note_apple: "Què és la 🍎 de la finestra de notes, i es pot amagar?",
    settings_quick_note_apple_label: "Mostrar la drecera 🍎 als àpats desats a la finestra de notes",
    faq_a_vision_board_today: "A «Els Meus Objectius», a sota del camí d'un objectiu (a «El pla»), toca 📅 al costat d'una fita i tria una data. També pots activar «🔁 Cada setmana fins que es completi» – llavors torna cada setmana el mateix dia fins que la marquis una vegada. La fita apareix aquell dia al Meu Dia i al calendari (i a Google Calendar, si està connectat), i el botó mostra quan està programada. Un ✓ en qualsevol dels dos llocs la marca també a l'altre i fa avançar el camí de l'objectiu. Torna a tocar 📅 per canviar la data o treure-la del calendari. Eliminar del calendari una tasca puntual també elimina la fita de l'objectiu; eliminar una setmana d'un recordatori setmanal només treu aquella setmana.",
    faq_q_vision_board_today: "Com poso una fita d'un objectiu al calendari (📅)?",
    vision_milestone_already_today: "Aquesta fita ja és a les tasques d'avui.",
    auth_consent_required: "Per registrar-se cal acceptar les Condicions d'ús i la Política de privadesa.",
    auth_consent_privacy: "Política de privadesa",
    auth_consent_terms: "Condicions d'ús",
    auth_consent_label: "He llegit i accepto les {terms} i la {privacy}, i tinc 16 anys o més.",
    nm_bonus_sub: "Una lectura breu sobre pesar-se, passar-se de l'objectiu i menjar fora",
    nm_bonus_label: "Bonus",
    nm_shortcut_title: "New Me – el meu menú d'avui",
    nm_remove: "Treu",
    nm_split_line: "Pla {plan} · Begudes {drinks} · Extres {extra}",
    nm_extras_hint: "Del Registre Diari d'Àpats i de l'afegit ràpid – ja comptat a l'anell.",
    nm_extras_title: "Avui, fora del pla",
    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Introdueix el nom de la beguda i les calories",
    nm_drink_more: "+ Una altra beguda",
    nm_drink_add: "Afegeix",
    nm_drink_name_ph: "Beguda (p. ex. suc)",
    nm_drinks_hint: "Només cal escriure la beguda – les calories es calculen automàticament i el número es pot canviar.",
    nm_slot_drinks: "Begudes",
    faq_a_new_me_tracking: "Toca la propera missió a dalt de New Me i després ✓ He menjat per marcar que el següent àpat ja s'ha menjat – el menú complet amb ✓ a cada àpat és a Tot el dia, al costat, i els àpats d'avui també apareixen a El Meu Dia a la pantalla d'inici – tocar-ne un allà (o passar-hi el ratolí per sobre) mostra exactament què cal menjar, amb ✓ i Canvia. Tot se sincronitza amb el Registre Diari d'Àpats: els àpats del pla, les begudes i tot el que afegeixis en un altre lloc (per exemple, un cafè des de l'afegit ràpid) es compten junts a New Me i a El Meu Dia – no se sobreescriu res del que ja has escrit, i treure un ✓ només treu la part de New Me. Quan tots els àpats d'avui estan marcats hi ha una petita celebració. A «Begudes» s'apunten les begudes del dia – totes juntes fins a ~150 kcal, és a dir, unes 3 begudes de fins a ~50 kcal cadascuna. Només cal escriure el nom de la beguda i les calories s'omplen automàticament amb IA. Les dues files de cafè/te també tenen un camp «Llet? Quanta?» (per exemple «una mica» o «50 ml»), i el càlcul s'actualitza; el número es pot canviar abans d'afegir i també després. Una beguda amb nom i calories es desa automàticament quan passes a una altra cosa – tocar Afegeix és opcional. Toca ☆ al costat d'una beguda per desar-la com a habitual – les begudes habituals apareixen com a botons a dalt de la targeta de Begudes, i un toc les afegeix al dia. ⭐ desa un àpat com a àpat desat. «Taula diària» mostra el que has menjat amb calories i proteïna. El petit 💎 al costat del mode concentració, a dalt de la pantalla d'inici, l'obre directament. Els valors de calories i proteïna són estimacions d'IA i poden contenir errors. No t'ho has menjat tot? Sota un àpat marcat, «No m'ho he menjat tot?» treu un quart, la meitat o tres quarts de la ració – o el que escriguis, calculat – i les calories del dia s'actualitzen.",
    faq_q_new_me_tracking: "Com funcionen el ✓, els canvis i les calories a New Me?",
    faq_a_new_me_what: "New Me és un programa de menú diari independent amb dos plans a punt – 1.300 o 1.500 calories – formats per 2 àpats principals i 2 berenars, amb 3 opcions per a cadascun. Inclou tot Premium. Preu: $11.99 al mes (cancel·lable quan vulguis) o $99.99 una sola vegada, per a tota la vida. S'obre des de 💎 New Me al menú. Abans de començar hi ha un qüestionari curt que comença amb un avís mèdic que cal acceptar. El programa és només informació general i no substitueix un metge ni un dietista clínic.",
    faq_q_new_me_what: "Què és New Me i com el puc obtenir?",
