    food_estimate_confirm_summary: "Estimat: {calories} kcal · {protein}g de proteïna", food_estimate_confirm_btn: "✓ Sembla correcte, continua", food_estimate_reject_btn: "✗ No és correcte", food_estimate_reject_question: "Què no és correcte? Descriu-ho de nou, o afegeix els detalls que falten.",
