    calorie_stat_avg_label: "Mitjana: {amount}",
    daily_focus_modal_title: "🧠 Quina és la cosa més important que has de fer avui?", daily_focus_modal_subtitle: "Respon, i s'afegirà directament a l'horari d'avui.", daily_focus_input_placeholder: "Avui el que més vull és", daily_focus_save_btn: "Afegir a l'horari d'avui", daily_focus_skip_btn: "Ara no", daily_focus_missing_text: "Escriu alguna cosa primer", daily_focus_added_toast: "Afegit a l'horari d'avui", daily_focus_other_option: "✍️ Altre...",
    daily_focus_c1_d0: "Protegir el meu espai de tranquil·litat davant el soroll del voltant", daily_focus_c1_d1: "Posar límits clars, amb amor i sense culpa", daily_focus_c1_d2: "Mantenir-me ancorat/da encara que hi hagi tempesta al voltant", daily_focus_c1_d3: "Fer de la meva calma i la meva energia la prioritat número u", daily_focus_c1_d4: "No carregar amb els sentiments i els estats d'ànim dels altres", daily_focus_c1_d5: "No deixar que les paraules dels altres debilitin la meva autoestima",
    daily_focus_c2_d0: "Escoltar el que el meu cos i la meva ment necessiten", daily_focus_c2_d1: "Gaudir de les petites coses pel camí", daily_focus_c2_d2: "Alentir el ritme i connectar de veritat amb mi mateix/a", daily_focus_c2_d3: "Donar-me espai per respirar enmig de la feina", daily_focus_c2_d4: "Sentir-me com a casa i en pau amb mi mateix/a", daily_focus_c2_d5: "Centrar-me en el que passa ara, sense córrer cap endavant",
