    faq_q_daily_focus_prompt: "Què és el petit recordatori que em pregunta què és el més important que he de fer avui?", faq_a_daily_focus_prompt: "És un recordatori diari Premium: un cop al dia apareix una petita insígnia «1» a la icona de l'assistent d'IA. Toca la insígnia per obrir una bombolla que et pregunta què és el més important per a tu avui, on de seguida apareixen 5 suggeriments ja preparats (canvien cada dia i van rotant per un any sencer de temes diferents perquè no es repeteixin) més 'Altre' per escriure el teu - en pots triar més d'un. Toca Afegir, i les teves tries apareixen com a petites etiquetes de recordatori a la part superior de 'El Meu Dia' (no són tasques per marcar). Si la tanques amb ✕ o toques fora, la insígnia només s'esvaeix durant la resta del dia en lloc de desaparèixer. Està activat per defecte, però el pots desactivar a Configuració > Personalització i calendari. Avui no és el dia? Toca «🌙 Avui no»: la insígnia desapareix fins demà, quan la pregunta torna com sempre. Un dels suggeriments ve de la teva pròpia vida – el següent pas de l'objectiu del mes o la lectura d'avui. Cada dia comença de nou.",
